def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def atomic_write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.tmp.{os.getpid()}")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def atomic_save_npz(path: Path, **arrays: np.ndarray) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.tmp.{os.getpid()}")
    with tmp.open("wb") as f:
        np.savez(f, **arrays)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def jsonable(value: Any) -> Any:
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, np.generic):
        return value.item()
    if torch.is_tensor(value):
        return value.detach().cpu().tolist()
    if callable(value):
        return getattr(value, "__qualname__", repr(value))
    if isinstance(value, dict):
        return {str(k): jsonable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [jsonable(v) for v in value]
    return repr(value)


def inject_torch_compatibility_shim() -> None:
    import torch.nn.modules.transformer as tm

    aliases = {
        "Optional": typing.Optional,
        "Module": torch.nn.Module,
        "Tensor": torch.Tensor,
        "MultiheadAttention": torch.nn.MultiheadAttention,
        "Linear": torch.nn.Linear,
        "Dropout": torch.nn.Dropout,
        "LayerNorm": torch.nn.LayerNorm,
    }
    for name, value in aliases.items():
        if not hasattr(tm, name):
            setattr(tm, name, value)


class OfficialTabPFNV1CausalSCMRegression:
    """Thin runtime adapter around unmodified official v1 prior source files."""

    def __init__(self, repo: Path):
        repo = repo.resolve()
        commit = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=repo, text=True).strip()
        if commit != EXPECTED_COMMIT:
            raise RuntimeError(f"expected official TabPFN v1 commit {EXPECTED_COMMIT}, got {commit}")
        checkpoint = repo / CHECKPOINT_REL
        if not checkpoint.is_file():
            raise FileNotFoundError(checkpoint)
        inject_torch_compatibility_shim()

        # Avoid the obsolete eager v1 inference initializer while executing the
        # official prior package itself.  The released prior-bag logits select
        # the MLP branch, so fast_gp only needs an import-time base-class stub.
        tabpfn_pkg = types.ModuleType("tabpfn")
        tabpfn_pkg.__path__ = [str(repo / "tabpfn")]
        tabpfn_pkg.__package__ = "tabpfn"
        sys.modules["tabpfn"] = tabpfn_pkg

        class UnusedExactGP(torch.nn.Module):
            def __init__(self, *args, **kwargs):
                super().__init__()

        gpytorch_stub = types.ModuleType("gpytorch")
        gpytorch_stub.models = types.SimpleNamespace(ExactGP=UnusedExactGP)
        sys.modules["gpytorch"] = gpytorch_stub

        from tabpfn.priors import differentiable_prior, flexible_categorical, mlp
        from tabpfn.priors.utils import uniform_int_sampler_f

        config = torch.load(checkpoint, map_location="cpu", weights_only=False)[2]
        config["num_classes"] = lambda: 0
        config["differentiable_hyperparameters"]["prior_mlp_activations"]["choice_values"] = [
            torch.nn.Tanh,
            torch.nn.Identity,
            torch.nn.ReLU,
        ]
        config["differentiable_hyperparameters"]["is_causal"] = {
            "distribution": "meta_choice",
            # The v1 meta_choice implementation assumes at least two entries.
            # Duplicating True preserves the official sampler machinery while
            # conditioning every draw on the causal SCM branch.
            "choice_values": [True, True],
        }
        config["normalize_labels"] = False
        config["check_is_compatible"] = False

        self.repo = repo
        self.checkpoint = checkpoint
        self.checkpoint_sha256 = sha256(checkpoint)
        self.config = config
        self.mlp = mlp
        self.flexible = flexible_categorical
        self.diff = differentiable_prior
        self.uniform_int_sampler_f = uniform_int_sampler_f
        self.last_sampled_hyperparameters: dict[str, Any] = {}

        original_sample = self.diff.DifferentiableHyperparameterList.sample_parameter_object

        def capture_sample(obj):
            result = original_sample(obj)
            self.last_sampled_hyperparameters = result[0].copy()
            return result

        self.diff.DifferentiableHyperparameterList.sample_parameter_object = capture_sample

    def generate(self, n: int, q: int) -> tuple[np.ndarray, np.ndarray, dict[str, Any]]:
        config = dict(self.config)
        config["seq_len_used"] = int(n)
        config["num_features"] = int(q)
        config["num_features_used"] = self.uniform_int_sampler_f(int(q), int(q))
        config["num_classes"] = lambda: 0

        def base(**kwargs):
            return self.mlp.get_batch(**kwargs)

        def flex(**kwargs):
            return self.flexible.get_batch(get_batch=base, **kwargs)

        out = self.diff.get_batch(
            batch_size=1,
            seq_len=int(n),
            num_features=int(q),
            get_batch=flex,
            device="cpu",
            differentiable_hyperparameters=config["differentiable_hyperparameters"],
            hyperparameters=config,
            batch_size_per_gp_sample=1,
            single_eval_pos=max(1, int(n) // 2),
        )
        x = out[0][:, 0].detach().cpu().numpy().astype(np.float32, copy=False)
        y = out[1][:, 0].detach().cpu().numpy().astype(np.float32, copy=False).reshape(-1)
        if x.shape != (n, q) or y.shape != (n,):
            raise RuntimeError(f"official prior shape mismatch: X={x.shape}, y={y.shape}, expected {(n, q)}")
        if not np.isfinite(x).all() or not np.isfinite(y).all():
            raise ValueError("nonfinite official prior task")
        if float(np.std(y)) <= 1e-7 or int(np.count_nonzero(np.std(x, axis=0) > 1e-7)) < q:
            raise ValueError("degenerate official prior task")
        hp = jsonable(self.last_sampled_hyperparameters)
        if hp.get("is_causal") is not True:
            raise RuntimeError(f"causal SCM policy violation: is_causal={hp.get('is_causal')!r}")
        return x, y, hp


def standardize(x: np.ndarray, eps: float = 1e-7) -> np.ndarray:
    x = np.asarray(x, dtype=np.float32)
    mu = x.mean(axis=0, keepdims=True)
    sd = x.std(axis=0, keepdims=True)
    if not np.isfinite(mu).all() or not np.isfinite(sd).all():
        raise ValueError("nonfinite standardization statistics")
    sd = np.where(sd > eps, sd, 1.0)
    return np.nan_to_num((x - mu) / sd, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float32)


def log_uniform(rng: np.random.Generator, lo: float, hi: float) -> float:
    return float(np.exp(rng.uniform(math.log(lo), math.log(hi))))


def activation(x: np.ndarray, name: str) -> np.ndarray:
    if name == "tanh":
        return np.tanh(x)
    if name == "relu":
        return np.maximum(x, 0.0)
    if name == "sigmoid":
        return 1.0 / (1.0 + np.exp(-np.clip(x, -30.0, 30.0)))
    if name == "sin_pi":
        return np.sin(np.pi * x)
    return 0.5 * x * (1.0 + np.tanh(np.sqrt(2.0 / np.pi) * (x + 0.044715 * x**3)))


def random_mlp512_scale_preserving(
    source: np.ndarray,
    rng: np.random.Generator,
    *,
    hidden_dim: int,
    gaussian_dims: int,
    input_noise_variance_min: float,
    input_noise_variance_max: float,
    output_noise_variance_min: float,
    output_noise_variance_max: float,
) -> tuple[np.ndarray, dict[str, Any]]:
    n, p = source.shape
    k = int(rng.integers(1, min(512, p) + 1))
    parents = rng.choice(p, size=k, replace=False)
    parent_x = standardize(source[:, parents].astype(np.float32, copy=False))
    input_variance = log_uniform(rng, input_noise_variance_min, input_noise_variance_max)
    gaussian_unit = standardize(rng.normal(0.0, 1.0, size=(n, gaussian_dims)).astype(np.float32))
    gaussian = gaussian_unit * math.sqrt(input_variance)
    inp = np.concatenate([parent_x, gaussian], axis=1)

    act = str(rng.choice(["gelu", "tanh", "relu", "sigmoid", "sin_pi"]))
    w1 = rng.normal(0.0, 1.0 / math.sqrt(inp.shape[1]), size=(inp.shape[1], hidden_dim)).astype(np.float32)
    b1 = rng.normal(0.0, 0.25, size=(hidden_dim,)).astype(np.float32)
    h = standardize(activation(inp @ w1 + b1[None, :], act))
    w2 = rng.normal(0.0, 1.0 / math.sqrt(hidden_dim), size=(hidden_dim, 512)).astype(np.float32)
    b2 = rng.normal(0.0, 0.10, size=(512,)).astype(np.float32)
    signal = standardize(h @ w2 + b2[None, :])
    output_variance = log_uniform(rng, output_noise_variance_min, output_noise_variance_max)
    output_noise = standardize(rng.normal(0.0, 1.0, size=signal.shape).astype(np.float32))
    out = standardize(signal + math.sqrt(output_variance) * output_noise)
    return out, {
        "parents": k,
        "gaussian_input_dims": int(gaussian_dims),
        "gaussian_input_variance": float(input_variance),
        "gaussian_input_realized_variance": float(np.var(gaussian, dtype=np.float64)),
        "parent_input_realized_variance": float(np.var(parent_x, dtype=np.float64)),
        "output_noise_variance": float(output_variance),
        "output_noise_realized_variance": float(np.var(math.sqrt(output_variance) * output_noise, dtype=np.float64)),
        "output_signal_realized_variance": float(np.var(signal, dtype=np.float64)),
        "noise_scale_contract": "scale_after_standardization_v1",
        "hidden_dim": int(hidden_dim),
        "activation": act,
    }


class ExactLowCorrelationAccumulator:
    """Incrementally retain float16 columns with exact all-pair certification."""

    def __init__(self, n: int, threshold: float, device: torch.device, clip_value: float):
        self.n = int(n)
        self.threshold = float(threshold)
        self.device = device
        self.clip_value = float(clip_value)
        self.stored_chunks: list[np.ndarray] = []
        self.z: torch.Tensor | None = None
        self.max_abs_corr = 0.0
        self.total_candidates = 0
        self.dropped_constant = 0
        self.dropped_cross = 0
        self.dropped_within = 0

    @property
    def p(self) -> int:
        return 0 if self.z is None else int(self.z.shape[1])

    def stored(self) -> np.ndarray:
        if not self.stored_chunks:
            return np.empty((self.n, 0), dtype=np.float16)
        return np.concatenate(self.stored_chunks, axis=1)

    def _prepare(self, candidate: np.ndarray) -> tuple[np.ndarray, torch.Tensor]:
        candidate = standardize(candidate)
        if self.clip_value > 0:
            candidate = np.clip(candidate, -self.clip_value, self.clip_value)
        stored = candidate.astype(np.float16)
        roundtrip = stored.astype(np.float32)
        centered = roundtrip - roundtrip.mean(axis=0, keepdims=True)
        norms = np.linalg.norm(centered.astype(np.float64), axis=0).astype(np.float32)
        keep = np.isfinite(norms) & (norms > 1e-7 * math.sqrt(max(1, self.n - 1)))
        self.dropped_constant += int((~keep).sum())
        stored = stored[:, keep]
        centered = centered[:, keep]
        norms = norms[keep]
        z = torch.as_tensor(centered, device=self.device, dtype=torch.float32)
        z = z / torch.as_tensor(norms, device=self.device, dtype=torch.float32).clamp_min(1e-12)[None, :]
        return stored, z

    @staticmethod
    def _one_per_component(conflicts: np.ndarray) -> np.ndarray:
        q = int(conflicts.shape[0])
        parent = np.arange(q, dtype=np.int64)

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = int(parent[a])
            return a

        rows, cols = np.nonzero(np.triu(conflicts, 1))
        for a, b in zip(rows.tolist(), cols.tolist()):
            ra, rb = find(int(a)), find(int(b))
            if ra != rb:
                parent[rb] = ra
        seen: set[int] = set()
        keep: list[int] = []
        for j in range(q):
            root = find(j)
            if root not in seen:
                seen.add(root)
                keep.append(j)
        return np.asarray(keep, dtype=np.int64)

    @torch.no_grad()
    def add(self, candidate: np.ndarray, limit: int | None = None) -> int:
        self.total_candidates += int(candidate.shape[1])
        stored, zc = self._prepare(candidate)
        if zc.shape[1] == 0:
            return 0

        cross_max = torch.zeros(zc.shape[1], device=self.device, dtype=torch.float32)
        if self.z is not None:
            block = 16384
            for start in range(0, self.z.shape[1], block):
                corr = self.z[:, start : start + block].T @ zc
                cross_max = torch.maximum(cross_max, corr.abs().amax(dim=0))
            cross_conflict = cross_max >= self.threshold
            self.dropped_cross += int(cross_conflict.sum().item())
            keep_cross = torch.nonzero(~cross_conflict, as_tuple=False).squeeze(1)
            stored = stored[:, keep_cross.detach().cpu().numpy()]
            zc = zc.index_select(1, keep_cross)
            cross_max = cross_max.index_select(0, keep_cross)
        if zc.shape[1] == 0:
            return 0

        corr_within = zc.T @ zc
        conflicts = (corr_within.abs() >= self.threshold).detach().cpu().numpy()
        np.fill_diagonal(conflicts, False)
        keep_within = self._one_per_component(conflicts)
        self.dropped_within += int(zc.shape[1] - keep_within.size)
        if limit is not None:
            keep_within = keep_within[: max(0, int(limit))]
        if keep_within.size == 0:
            return 0

        keep_t = torch.as_tensor(keep_within, device=self.device, dtype=torch.long)
        accepted_z = zc.index_select(1, keep_t)
        accepted_stored = stored[:, keep_within]
        if self.z is not None and cross_max.numel():
            accepted_cross_max = cross_max.index_select(0, keep_t).amax().item()
            self.max_abs_corr = max(self.max_abs_corr, float(accepted_cross_max))
        if accepted_z.shape[1] > 1:
            accepted_corr = (accepted_z.T @ accepted_z).abs()
            accepted_corr.fill_diagonal_(0.0)
            self.max_abs_corr = max(self.max_abs_corr, float(accepted_corr.amax().item()))
        self.stored_chunks.append(accepted_stored)
        self.z = accepted_z if self.z is None else torch.cat([self.z, accepted_z], dim=1)
        if not self.max_abs_corr < self.threshold:
            raise RuntimeError(
                f"correlation certification failure: max={self.max_abs_corr} threshold={self.threshold}"
            )
        return int(accepted_z.shape[1])


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser()
    p.add_argument("--out-dir", type=Path, required=True)
    p.add_argument("--official-repo", type=Path, required=True)
    p.add_argument("--num-batches", type=int, default=1000000)
    p.add_argument("--batch-size", type=int, default=4)
    p.add_argument("--start-index", type=int, default=-1, help="negative means resume after highest completed batch")
    p.add_argument("--stop-file", type=Path, default=None)
    p.add_argument("--target-bytes", type=int, default=0, help="stop after atomic NPZ bytes in this worker root reach target")
    p.add_argument("--seed", type=int, default=88072900)
    p.add_argument("--threads", type=int, default=4)
    p.add_argument("--n-min", type=int, default=32)
    p.add_argument("--n-max", type=int, default=40000)
    p.add_argument("--main-n-min", type=int, default=200)
    p.add_argument("--small-n-max", type=int, default=199)
    p.add_argument("--small-n-probability", type=float, default=0.10)
    p.add_argument("--p-min", type=int, default=50)
    p.add_argument("--p-max", type=int, default=200000)
    p.add_argument("--max-cells", type=int, default=24000000)
    p.add_argument("--p-median", type=float, default=10000.0)
    p.add_argument("--p-log-sigma", type=float, default=0.75)
    p.add_argument("--raw-n-median", type=float, default=5700.0)
    p.add_argument("--n-log-sigma", type=float, default=0.70)
    p.add_argument("--direct-p-cap", type=int, default=4096)
    p.add_argument("--corr-threshold", type=float, default=0.95)
    p.add_argument("--hidden-dim", type=int, default=256)
    p.add_argument("--gaussian-dims", type=int, default=16)
    p.add_argument("--input-noise-variance-min", type=float, default=1e-3)
    p.add_argument("--input-noise-variance-max", type=float, default=1.0)
    p.add_argument("--output-noise-variance-min", type=float, default=1e-3)
    p.add_argument("--output-noise-variance-max", type=float, default=0.25)
    p.add_argument("--linear-support-min", type=int, default=1)
    p.add_argument("--linear-support-max", type=int, default=64)
    p.add_argument("--snr-min", type=float, default=3.0)
    p.add_argument("--snr-max", type=float, default=30.0)
    p.add_argument("--clip-value", type=float, default=10.0)
    p.add_argument("--max-retries", type=int, default=30)
    p.add_argument("--force-n", type=int, default=None)
    p.add_argument("--force-p", type=int, default=None)
    p.add_argument("--corr-device", default="cuda")
    return p.parse_args()


def load_entries(path: Path) -> list[dict[str, Any]]:
    if not path.is_file():
        return []
    payload = json.loads(path.read_text(encoding="utf-8"))
    return list(payload.get("files", []))


def write_manifest(args: argparse.Namespace, entries: list[dict[str, Any]], repo_commit: str, checkpoint_sha: str) -> None:
    payload = {
        "generator": GENERATOR_NAME,
        "prior": PRIOR_NAME,
        "dataset_contract": DATASET_CONTRACT,
        "num_datasets": int(sum(int(e["num_tasks"]) for e in entries)),
        "settings": {
            "shape_sampler": SHAPE_SAMPLER_NAME,
            "fixed_batch_size": True,
            "batch_size": int(args.batch_size),
            "n_min": int(args.n_min),
            "n_max": int(args.n_max),
            "main_n_min": int(args.main_n_min),
            "small_n_max": int(args.small_n_max),
            "small_n_probability": float(args.small_n_probability),
            "p_min": int(args.p_min),
            "p_max": int(args.p_max),
            "max_cells": int(args.max_cells),
            "direct_p_cap": int(args.direct_p_cap),
            "official_tabpfn_tag": "v1.0.0",
            "official_tabpfn_commit": repo_commit,
            "official_checkpoint_sha256": checkpoint_sha,
            "official_prior_conditioning": "causal SCM branch only (is_causal=True)",
            "official_core_prior": OFFICIAL_CORE_PRIOR,
            "causal_policy": CAUSAL_POLICY,
            "noncausal_bnn_used": False,
            "official_target_usage": "discarded; replaced by shared Exp122 sparse-linear target on final stored X",
            "correlation_threshold_exclusive": float(args.corr_threshold),
            "correlation_certification": "exact incremental all-pair Pearson after float16 roundtrip",
            "mlp_parent_count": "discrete uniform 1..min(512,current_P)",
            "mlp_output_features": 512,
            "mlp_hidden_dim": int(args.hidden_dim),
            "gaussian_input_dims": int(args.gaussian_dims),
            "input_noise_variance_range": [args.input_noise_variance_min, args.input_noise_variance_max],
            "output_noise_variance_range": [args.output_noise_variance_min, args.output_noise_variance_max],
            "target_contract": TARGET_CONTRACT,
            "target_seed_contract": TARGET_SEED_CONTRACT,
            "linear_support_rule": "log-uniform 1..min(64,max(1,floor(N/16)),P)",
            "linear_support_range": [args.linear_support_min, args.linear_support_max],
            "target_snr_distribution": "log_uniform",
            "target_snr_range": [args.snr_min, args.snr_max],
            "batch_rng_contract": (
                "seed=(worker_seed+1000003*batch_index) mod (2^32-1); "
                "restart-stable for a fixed source/config/PYTHONHASHSEED"
            ),
        },
        "files": sorted(entries, key=lambda e: e["path"]),
    }
    atomic_write_json(args.out_dir / "manifest.json", payload)


def main() -> None:
    args = parse_args()
    if (args.force_n is None) != (args.force_p is None):
        raise ValueError("force-n and force-p must be provided together")
    if not math.isclose(args.corr_threshold, REQUIRED_CORRELATION_THRESHOLD, rel_tol=0.0, abs_tol=1e-12):
        raise ValueError(
            f"corr-threshold must equal {REQUIRED_CORRELATION_THRESHOLD}; got {args.corr_threshold}"
        )
    if args.max_cells < args.n_min * args.p_max:
        raise ValueError("max-cells must permit n-min at p-max")
    if not (args.n_min <= args.small_n_max < args.main_n_min <= args.n_max):
        raise ValueError("invalid small/main N bounds")
    if not (1 <= args.linear_support_min <= args.linear_support_max):
        raise ValueError("invalid sparse-linear support range")
    if not torch.cuda.is_available() and args.corr_device.startswith("cuda"):
        raise RuntimeError("exact correlation certification requested on CUDA but CUDA is unavailable")

    os.environ["OMP_NUM_THREADS"] = str(args.threads)
    os.environ["MKL_NUM_THREADS"] = str(args.threads)
    os.environ["OPENBLAS_NUM_THREADS"] = str(args.threads)
    torch.set_num_threads(args.threads)
    random.seed(args.seed)
    np.random.seed(args.seed % (2**32 - 1))
    torch.manual_seed(args.seed % (2**32 - 1))
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(args.seed % (2**32 - 1))
    device = torch.device(args.corr_device)
    args.out_dir.mkdir(parents=True, exist_ok=True)
    entries = load_entries(args.out_dir / "manifest.json")
    if args.start_index < 0:
        completed = [int(Path(e["path"]).stem.split("_")[-1]) for e in entries]
        start_index = max(completed, default=-1) + 1
    else:
        start_index = int(args.start_index)

    official = OfficialTabPFNV1CausalSCMRegression(args.official_repo)
    commit = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=args.official_repo, text=True).strip()
    print(
        f"official TabPFN v1 low-corr generator start part={args.out_dir.name} seed={args.seed} "
        f"start={start_index} device={device} threads={args.threads}",
        flush=True,
    )

    for offset in range(args.num_batches):
        batch_index = start_index + offset
        if args.stop_file is not None and args.stop_file.exists():
            print(f"stop file observed: {args.stop_file}", flush=True)
            break
        current_bytes = sum(path.stat().st_size for path in args.out_dir.glob("batch_*.npz"))
        if args.target_bytes > 0 and current_bytes >= args.target_bytes:
            print(f"deterministic worker byte target reached: {current_bytes} >= {args.target_bytes}", flush=True)
            break
        # A batch must be a pure function of (source, config, worker seed,
        # batch index).  Replaying from a partially completed worker root must
        # therefore not consume the RNG stream for all earlier batches.
        batch_seed = int((int(args.seed) + 1_000_003 * int(batch_index)) % (2**32 - 1))
        random.seed(batch_seed)
        np.random.seed(batch_seed)
        torch.manual_seed(batch_seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(batch_seed)
        rng = np.random.default_rng(batch_seed)
        n, p = (
            (int(args.force_n), int(args.force_p))
            if args.force_n is not None
            else sample_shape_pair(
                rng,
                n_min=args.n_min,
                n_max=args.n_max,
                main_n_min=args.main_n_min,
                small_n_max=args.small_n_max,
                small_n_probability=args.small_n_probability,
                p_min=args.p_min,
                p_max=args.p_max,
                max_cells=args.max_cells,
                p_median=args.p_median,
                p_log_sigma=args.p_log_sigma,
                raw_n_median=args.raw_n_median,
                n_log_sigma=args.n_log_sigma,
            )
        )
        if not (args.n_min <= n <= args.n_max and args.p_min <= p <= args.p_max):
            raise ValueError(f"shape outside contract: N={n}, P={p}")
        if n * p > args.max_cells:
            raise ValueError(f"shape exceeds max cells: N={n}, P={p}")
        t0 = time.time()
        xs: list[np.ndarray] = []
        ys: list[np.ndarray] = []
        task_meta: list[dict[str, Any]] = []

        for task_index in range(args.batch_size):
            last_error: str | None = None
            for attempt in range(args.max_retries):
                try:
                    q = min(p, args.direct_p_cap)
                    core, _official_y, hp = official.generate(n, q)
                    acc = ExactLowCorrelationAccumulator(n, args.corr_threshold, device, args.clip_value)
                    acc.add(core, limit=p)
                    is_direct = p <= args.direct_p_cap
                    if is_direct and acc.p < args.p_min:
                        raise ValueError(
                            f"official direct core retained only {acc.p} features, below stored minimum {args.p_min}"
                        )
                    mlp_meta: list[dict[str, Any]] = []
                    chunk_attempts = 0
                    while not is_direct and acc.p < p:
                        chunk_attempts += 1
                        if chunk_attempts > 8 * math.ceil((p - q + 1) / 512) + 32:
                            raise RuntimeError(f"too many MLP fill attempts at retained={acc.p}, target={p}")
                        candidate, meta = random_mlp512_scale_preserving(
                            acc.stored().astype(np.float32),
                            rng,
                            hidden_dim=args.hidden_dim,
                            gaussian_dims=args.gaussian_dims,
                            input_noise_variance_min=args.input_noise_variance_min,
                            input_noise_variance_max=args.input_noise_variance_max,
                            output_noise_variance_min=args.output_noise_variance_min,
                            output_noise_variance_max=args.output_noise_variance_max,
                        )
                        before = acc.p
                        accepted = acc.add(candidate, limit=p - acc.p)
                        meta.update({"candidate_features": 512, "accepted_features": accepted, "retained_before": before})
                        mlp_meta.append(meta)
                    stored_p = min(p, acc.p) if is_direct else p
                    x = acc.stored()[:, :stored_p]
                    perm = rng.permutation(stored_p)
                    x = x[:, perm]
                    target_seed = derive_target_seed(args.seed, batch_index, task_index)
                    y, y_meta = make_controlled_sparse_linear_target(
                        x,
                        target_seed=target_seed,
                        support_min=args.linear_support_min,
                        support_max=min(args.linear_support_max, max(1, n // 16)),
                        snr_min=args.snr_min,
                        snr_max=args.snr_max,
                        clip_value=args.clip_value,
                    )
                    if x.shape != (n, stored_p) or not np.isfinite(x).all() or not np.isfinite(y).all():
                        raise RuntimeError("final task validation failed")
                    if not acc.max_abs_corr < args.corr_threshold:
                        raise RuntimeError("final exact correlation certificate failed")
                    xs.append(x.astype(np.float16, copy=False))
                    ys.append(y.astype(np.float32, copy=False))
                    task_meta.append(
                        {
                            "task_index": task_index,
                            "attempt": attempt + 1,
                            "official_sampled_hyperparameters": hp,
                            "mode": "direct_tabpfn_v1_causal_scm" if is_direct else "tabpfn_v1_causal_scm_plus_random_mlp512",
                            "causal_policy": CAUSAL_POLICY,
                            "noncausal_bnn_used": False,
                            "requested_p": int(p),
                            "stored_p": int(stored_p),
                            "exact_max_abs_corr": float(acc.max_abs_corr),
                            "candidates": int(acc.total_candidates),
                            "dropped_constant": int(acc.dropped_constant),
                            "dropped_cross": int(acc.dropped_cross),
                            "dropped_within": int(acc.dropped_within),
                            "mlp_chunks": mlp_meta,
                            "display_permutation_sha256": hashlib.sha256(perm.astype(np.int64).tobytes()).hexdigest(),
                            **y_meta,
                        }
                    )
                    break
                except Exception as exc:  # noqa: BLE001
                    last_error = repr(exc)
                    if torch.cuda.is_available():
                        torch.cuda.empty_cache()
            else:
                raise RuntimeError(f"task {task_index} failed after {args.max_retries} attempts: {last_error}")

        out_path = args.out_dir / f"batch_{batch_index:06d}.npz"
        max_corr = np.asarray([m["exact_max_abs_corr"] for m in task_meta], dtype=np.float32)
        snr = np.asarray([m["target_snr"] for m in task_meta], dtype=np.float32)
        target_seeds = np.asarray([m["target_seed"] for m in task_meta], dtype=np.uint64)
        atomic_save_npz(
            out_path,
            X=np.stack(xs),
            y=np.stack(ys),
            exact_max_abs_corr=max_corr,
            corr_threshold=np.full(args.batch_size, args.corr_threshold, dtype=np.float32),
            target_snr=snr,
            target_seed=target_seeds,
        )
        entry = {
            "path": out_path.name,
            "batch_seed": int(batch_seed),
            "bytes": int(out_path.stat().st_size),
            "num_tasks": int(args.batch_size),
            "n": int(n),
            "p": int(xs[0].shape[1]),
            "requested_p": int(p),
            "shape_sampler": SHAPE_SAMPLER_NAME,
            "prior": PRIOR_NAME,
            "official_core_prior": OFFICIAL_CORE_PRIOR,
            "causal_policy": CAUSAL_POLICY,
            "noncausal_bnn_used": False,
            "official_target_usage": "discarded",
            "target_contract": TARGET_CONTRACT,
            "correlation_threshold_exclusive": float(args.corr_threshold),
            "correlation_certification": "exact incremental all-pair Pearson after float16 roundtrip",
            "task_max_abs_corr_max": float(max_corr.max()),
            "task_max_abs_corr_mean": float(max_corr.mean()),
            "task_snr_min": float(snr.min()),
            "task_snr_median": float(np.median(snr)),
            "task_snr_max": float(snr.max()),
            "task_metadata": task_meta,
        }
        entries = [e for e in entries if e.get("path") != out_path.name]
        entries.append(entry)
        write_manifest(args, entries, commit, official.checkpoint_sha256)
        print(
            f"saved {out_path.name} tasks={args.batch_size} N={n} P={p} "
            f"bytes={out_path.stat().st_size} maxcorr={max_corr.max():.6f} dt={time.time()-t0:.1f}s",
            flush=True,
        )


if __name__ == "__main__":
    main()
